package com.vandorlabs.neoforge.screen;
import com.vandorlabs.screen.*;
import com.vandorlabs.persistence.*;
import com.vandorlabs.redstone.*;
import com.vandorlabs.neoforge.ModernHousingTags;
import com.vandorlabs.neoforge.redstone.*;
import com.vandorlabs.neoforge.shape.PanelPlayback;
import net.minecraft.core.*;
import net.minecraft.nbt.*;
import net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.block.entity.*;
import net.minecraft.world.level.block.state.BlockState;
import java.util.*;
/** Unregistered screen authority. Saved envelopes stay private; visual/editor data is explicitly projected. */
public class NativeScreenEntity extends BlockEntity implements NativeChannelMember {
 public interface Catalog extends NativeScreenSettings.Catalog,ScreenArtworkMigration.Catalog {int defaultHousing();boolean validFrame(int choice);boolean validFrameSurface(int choice);int screenArtwork(String id);int inputArtwork(String id);}
 public record Transmission(int range,boolean local,ChannelList channels){public Transmission{Objects.requireNonNull(channels);if(!TransmissionSettings.validRange(range))throw new IllegalArgumentException("Screen range");}}
 public record Visual(ScreenFamily family,NativeScreenSettings settings,FrameSettings frames,PanelPlayback glass,List<NativeScreenControls> controls,int effectivePower,int physicalPower,boolean inert,long geometryRevision,com.vandorlabs.screen.ScreenAppearance appearance){public Visual{controls=List.copyOf(controls);}}
 private record Snapshot(NativeScreenSettings settings,FrameSettings frames,PanelPlayback glass,List<NativeScreenControls> controls,int present,Transmission transmission){Snapshot{controls=List.copyOf(controls);}}
 private final NativeScreenControlService controlService;private NativeScreenActivation savedActivation;private final ScreenFamily family;private final Catalog catalog;private final Snapshot defaults;private volatile Snapshot snapshot;private CompoundTag retained=new CompoundTag();private boolean inert;private int physicalPower,notifiedOutput;private long geometryRevision;private volatile Visual visual;
 public NativeScreenEntity(BlockEntityType<?> type,BlockPos pos,BlockState state,ScreenFamily family,Catalog catalog){super(type,pos,state);this.family=Objects.requireNonNull(family);this.catalog=Objects.requireNonNull(catalog);CompoundTag fresh=NativeScreenFactory.choices(family,catalog,catalog.defaultHousing(),catalog.defaultFrame());defaults=decode(fresh);snapshot=defaults;savedActivation=snapshot.settings.activation();retained=fresh;publishLocal();controlService=new NativeScreenControlService(this);}
 public final ScreenFamily family(){return family;}public final NativeScreenSettings screenSettings(){return snapshot.settings;}public final Transmission transmission(){return snapshot.transmission;}public final Visual visual(){return visual;}public final boolean inert(){return inert;}public final NativeScreenControls controls(int slot){if(slot<0||slot>1)throw new IllegalArgumentException("Screen slot");return snapshot.controls.get(slot);}
 private Snapshot decode(CompoundTag tag){NativeScreenSettings settings=NativeScreenSettings.read(tag,catalog);var access=new ModernHousingTags(tag);FrameSettings frames=FrameSettings.read(access,catalog::validFrame,catalog::validFrameSurface,catalog::validMaterial);List<NativeScreenControls> controls=new ArrayList<>(2);int present=0;for(int slot=0;slot<2;slot++){String key=slot==0?"RedstonePrimary":"RedstoneSecondary";if(tag.contains(key,Tag.TAG_COMPOUND))present|=1<<slot;controls.add(NativeScreenControls.read(tag.getCompound(key),family.standaloneControlRows(slot)));}CompoundTag main=tag.getCompound("ForgeData").getCompound(TransmissionSettings.SETTINGS).getCompound("main");Transmission transmission=new Transmission(TransmissionSettings.readRange(main.contains("Range",Tag.TAG_INT),main.getInt("Range"),true),TransmissionSettings.readLocal(main.contains("Local",Tag.TAG_BYTE),main.getBoolean("Local"),false),TransmissionSettings.readChannels(main.contains("Channels",Tag.TAG_INT_ARRAY),main.getIntArray("Channels"),ChannelList.EMPTY));return new Snapshot(settings,frames,PanelPlayback.read(tag),controls,present,transmission);}
 private void publishLocal(){
  int power=inert?0:Math.max(snapshot.settings.channelLevel(),physicalPower);Visual previous=visual;
  com.vandorlabs.screen.ScreenAppearance appearance;
  if(inert)appearance=com.vandorlabs.screen.ScreenAppearance.DARK;
  else if(previous!=null&&!previous.inert&&previous.settings==snapshot.settings&&previous.frames==snapshot.frames&&previous.effectivePower==power&&(previous.physicalPower>0)==(physicalPower>0)&&previous.controls.get(0).enabled()==snapshot.controls.get(0).enabled()&&previous.controls.get(1).enabled()==snapshot.controls.get(1).enabled())appearance=previous.appearance;
  else appearance=NativeScreenAppearance.of(family,snapshot.settings,snapshot.frames,snapshot.controls,physicalPower,catalog);
  visual=new Visual(family,snapshot.settings,snapshot.frames,snapshot.glass,snapshot.controls,power,inert?0:physicalPower,inert,geometryRevision,appearance);
 }
 private void notifyWorld(){if(level==null)return;setChanged();level.sendBlockUpdated(worldPosition,getBlockState(),getBlockState(),2);if(!level.isClientSide){level.getChunkSource().getLightEngine().checkBlock(worldPosition);int output=localOutput();if(output!=notifiedOutput){notifiedOutput=output;level.updateNeighborsAt(worldPosition,getBlockState().getBlock());}}}
 private void changed(boolean geometry){if(geometry)geometryRevision++;publishLocal();setChanged();if(level instanceof ServerLevel&&NativeSignalUpdateBatch.isActive())NativeSignalUpdateBatch.afterSignals(this,this::notifyWorld);else notifyWorld();}
 @Override protected void loadAdditional(CompoundTag tag,HolderLookup.Provider registries){CompoundTag original=tag.copy();try{if(!NativeScreenOwnership.installable(original))throw new IllegalArgumentException("Deferred Screen ownership or selected surface");var transmission=NativeScreenTransmissionMigration.read(tag);CompoundTag migrated=NativeScreenArtworkMigration.normalize(transmission.install(),catalog);Snapshot next=decode(migrated);super.loadAdditional(migrated.copy(),registries);snapshot=next;savedActivation=next.settings.activation();retained=migrated;inert=level!=null&&level.isClientSide&&tag.getBoolean("NativeScreenInert");}catch(RuntimeException failure){snapshot=defaults;retained=original;inert=true;}physicalPower=level!=null&&level.isClientSide?NativeScreenProjection.power(tag):0;geometryRevision=level!=null&&level.isClientSide&&tag.contains("NativeScreenGeometryRevision",Tag.TAG_LONG)?Math.max(0,tag.getLong("NativeScreenGeometryRevision")):geometryRevision+1;publishLocal();controlService.savedChanged();if(level instanceof ServerLevel){if(inert)NativeRedstoneChannels.unregister(this);else NativeRedstoneChannels.queueRegistration(this);}}
 private void writeSnapshot(CompoundTag tag,boolean publicProjection){if(!publicProjection)for(String key:new String[]{"NativeScreenPower","NativeScreenGeometryRevision","NativeScreenInert"})tag.remove(key);snapshot.settings.write(tag);if(!publicProjection&&snapshot.settings.activation().equals(savedActivation)){if(retained.contains("DisplayActivation"))tag.put("DisplayActivation",retained.get("DisplayActivation").copy());else tag.remove("DisplayActivation");}snapshot.frames.write(new ModernHousingTags(tag));snapshot.glass.write(tag);for(int slot=0;slot<2;slot++){String key=slot==0?"RedstonePrimary":"RedstoneSecondary";if((snapshot.present&(1<<slot))!=0){CompoundTag row=publicProjection?new CompoundTag():tag.getCompound(key).copy();snapshot.controls.get(slot).write(row);tag.put(key,row);}else tag.remove(key);}CompoundTag forge=publicProjection?new CompoundTag():tag.getCompound("ForgeData").copy(),all=forge.getCompound(TransmissionSettings.SETTINGS).copy(),main=all.getCompound("main").copy();main.putInt("Range",snapshot.transmission.range);main.putBoolean("Local",snapshot.transmission.local);main.putIntArray("Channels",snapshot.transmission.channels.toArray());all.put("main",main);forge.put(TransmissionSettings.SETTINGS,all);tag.put("ForgeData",forge);}
 @Override protected void saveAdditional(CompoundTag tag,HolderLookup.Provider registries){tag.merge(retained.copy());if(inert)return;super.saveAdditional(tag,registries);writeSnapshot(tag,false);}
 @Override public CompoundTag getUpdateTag(HolderLookup.Provider registries){CompoundTag tag=new CompoundTag();writeSnapshot(tag,true);tag.putInt("NativeScreenPower",visual.physicalPower);tag.putLong("NativeScreenGeometryRevision",geometryRevision);if(inert)tag.putBoolean("NativeScreenInert",true);return tag;}
 @Override public ClientboundBlockEntityDataPacket getUpdatePacket(){return ClientboundBlockEntityDataPacket.create(this);}
 @Override public BlockEntity channelBlockEntity(){return this;}@Override public ChannelList getRedstoneChannels(){return inert?ChannelList.EMPTY:snapshot.settings.channels();}@Override public boolean isChannelMemberActive(){return !inert&&NativeChannelMember.super.isChannelMemberActive();}
 @Override public void setChannelLevel(int value){serverThread();if(inert||value<0||value>15||!(level instanceof ServerLevel)||!isChannelMemberActive()||snapshot.settings.channelLevel()==value)return;NativeScreenSettings old=snapshot.settings;ScreenData data=old.scalar();ScreenData scalar=new ScreenData(data.selectedScreen,data.redstoneEnabled,data.displayMode,data.framed,data.animationSpeedIndex,data.inputPanel,data.secondaryInputPanel,data.wallPosition,data.smallInput,data.redstoneChannel,value>0,data.housingTexture);NativeScreenSettings next=new NativeScreenSettings(scalar,old.housing(),old.activation(),old.channels(),value,old.inverted(),old.primarySurface(),old.secondarySurface(),old.ceilingMounted(),old.ceilingPosition(),old.surfaceLayout(),old.surfaceTileSides());snapshot=new Snapshot(next,snapshot.frames,snapshot.glass,snapshot.controls,snapshot.present,snapshot.transmission);changed(false);}
 @Override public void beforeChannelRegistration(){controlService.finishLoading();localInputChanged();}
 public final void localInputChanged(){serverThread();if(inert||!(level instanceof ServerLevel)||!isChannelMemberActive())return;int next=NativeLoadedRedstonePower.level(level,worldPosition);if(next!=physicalPower){physicalPower=next;changed(false);}}
 void reconcileControlOutput(){if(level instanceof ServerLevel&&isChannelMemberActive()&&localOutput()!=notifiedOutput)changed(false);}
 NativeScreenControlService controlService(){return controlService;}
 void installControlData(int slot,NativeScreenControls data,boolean notify){snapshot=new Snapshot(snapshot.settings,snapshot.frames,snapshot.glass,slot==0?List.of(data,snapshot.controls.get(1)):List.of(snapshot.controls.get(0),data),snapshot.present|1<<slot,snapshot.transmission);if(notify)changed(false);else{publishLocal();setChanged();}}
 public final int localOutput(){if(inert||!snapshot.transmission.local)return 0;int result=0;long now=level==null?0:level.getGameTime();for(var side:snapshot.controls)if(side.enabled())for(var row:side.rows())result=Math.max(result,row.slider()?row.level():row.active(now)?15:0);return result;}
 private void serverThread(){if(level instanceof ServerLevel server&&!server.getServer().isSameThread())throw new IllegalStateException("Screen authority requires the server thread");}
 @Override public void onLoad(){super.onLoad();if(level instanceof ServerLevel)NativeRedstoneChannels.queueRegistration(this);}
 @Override public void setRemoved(){if(level instanceof ServerLevel)NativeRedstoneChannels.unregister(this);controlService.stop();super.setRemoved();}
 @Override public void onChunkUnloaded(){if(level instanceof ServerLevel)NativeRedstoneChannels.unregister(this);controlService.stop();super.onChunkUnloaded();}
}
